{"kind":"FUNCTION","name":"hydrate_inquiry_context","owner":"postgres","result":"trigger","schema":"public","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.hydrate_inquiry_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
    offer_coffee_id uuid;
    offer_reference text;
    warehouse_code text;
    coffee_name text;
begin

    -- Authenticated users are always tied to their actual account.

    if auth.uid() is not null then
        new.user_id = auth.uid();
    end if;


    -- If offer exists, derive Coffee + Warehouse from DB.

    if new.offer_id is not null then

        select
            o.coffee_id,
            o.reference_number,
            w.code
        into
            offer_coffee_id,
            offer_reference,
            warehouse_code
        from public.coffee_offers o
        join public.warehouses w
          on w.id = o.warehouse_id
        where o.id = new.offer_id
          and o.deleted_at is null;

        if offer_coffee_id is null then
            raise exception 'Invalid offer';
        end if;

        if new.coffee_id is null then
            new.coffee_id = offer_coffee_id;
        elsif new.coffee_id <> offer_coffee_id then
            raise exception
                'Offer does not belong to selected coffee';
        end if;

        new.offer_reference_snapshot = offer_reference;
        new.warehouse_code_snapshot = warehouse_code;

    end if;


    -- Snapshot English name if available.
    -- Fallback to slug.

    if new.coffee_id is not null then

        select
            coalesce(
                (
                    select ct.name
                    from public.coffee_translations ct
                    where ct.coffee_id = c.id
                      and ct.locale = 'en'
                    limit 1
                ),
                c.slug
            )
        into coffee_name
        from public.coffees c
        where c.id = new.coffee_id;

        if coffee_name is null then
            raise exception 'Invalid coffee';
        end if;

        new.coffee_name_snapshot = coffee_name;

    end if;

    return new;

end;
$function$
","volatility":"VOLATILE","security_definer":true}

{"kind":"FUNCTION","name":"prevent_profile_role_escalation","owner":"postgres","result":"trigger","schema":"public","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.prevent_profile_role_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth'
AS $function$
begin

    if new.role is distinct from old.role then

        if
            current_user <> 'postgres'
            and coalesce(auth.jwt() ->> 'role', '') <> 'service_role'
        then

            raise exception
                'Profile role cannot be changed from the public application';

        end if;

    end if;

    return new;

end;
$function$
","volatility":"VOLATILE","security_definer":false}

