{"kind":"FUNCTION","name":"set_updated_at_and_user","owner":"postgres","result":"trigger","schema":"public","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.set_updated_at_and_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth'
AS $function$
begin
    new.updated_at = now();

    if auth.uid() is not null then
        new.updated_by = auth.uid();
    end if;

    return new;
end;
$function$
