{"kind":"FUNCTION","name":"validate_coffee_region_origin","owner":"postgres","result":"trigger","schema":"public","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.validate_coffee_region_origin()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth'
AS $function$
declare
    region_origin_id uuid;
begin

    if new.region_id is null then
        return new;
    end if;

    select r.origin_id
    into region_origin_id
    from public.regions r
    where r.id = new.region_id;

    if region_origin_id is null then
        raise exception 'Region does not exist';
    end if;

    if region_origin_id <> new.origin_id then
        raise exception
            'Coffee region must belong to the selected origin';
    end if;

    return new;

end;
$function$
","volatility":"VOLATILE","security_definer":false}
